//! Static interface messages in Russian, English, and Czech.

macro_rules! catalog {
    ($($russian:tt => ($english:literal, $czech:literal),)+) => {
        // Keep the original message as the literal key so adjacent code
        // remains readable. A missing key fails at the call site.
        macro_rules! checked_key {
            $(($russian) => { $crate::i18n::MessageKey::from_catalog($russian, $english, $czech) };)+
            ($missing:literal) => { compile_error!(concat!("Missing translation for: ", $missing)) };
        }

        #[cfg(test)]
        pub(super) const MESSAGES: &[super::MessageKey] = &[
            $(super::MessageKey::from_catalog($russian, $english, $czech),)+
        ];
    };
}

